const clone=value=>value==null?value:structuredClone(value);
const freeze=value=>{if(value&&typeof value==='object'&&!Object.isFrozen(value)){for(const child of Object.values(value))freeze(child);Object.freeze(value)}return value};
const uniq=list=>new Set(list).size===list.length;
const revisionAfter=value=>{const n=Number(value);return Number.isFinite(n)&&String(n)===String(value).trim()?String(n+1):`${String(value||'0')}.1`};
const EDGE_TYPES=new Set(['depends','success','failure','conditional','optional','branch']);

/** Lab definition truth only. Structured/Spatial mechanics remain shared Foundation owners. */
export class W03LabDomain {
  constructor({definition={id:'LAB-DRAFT',revision:'1',title:'',tasks:[],dependencies:[],requiredTools:[],environment:{capabilities:[]}},persistence=null,status='DRAFT'}={}){this.owner='W03LabDomain';this.definition=clone(definition);this.persistence=persistence;this.version=1;this.lifecycle=status;this.selection=null;this.publishedRevisions=[];this.sourceLineage=null;this.receipts=[]}
  snapshot(){return freeze({owner:this.owner,version:this.version,status:this.lifecycle,lifecycle:this.lifecycle,selection:clone(this.selection),sourceLineage:clone(this.sourceLineage),definition:clone(this.definition),publishedRevisions:clone(this.publishedRevisions.map(x=>({id:x.id,revision:x.revision,digest:x.digest||null}))),persistence:this.persistence?{status:'DELEGATED'}:{status:'UNAVAILABLE',reason:'Shared persistence not bound in this composition.'}})}
  _assertMutable(){if(this.lifecycle==='PUBLISHED')throw Error('LAB_PUBLISHED_REVISION_IMMUTABLE')}
  _receipt(action,detail={}){const receipt=freeze({owner:this.owner,action,version:this.version,lifecycle:this.lifecycle,...clone(detail)});this.receipts.push(receipt);return receipt}
  _edges(){return (this.definition.dependencies||[]).map((edge,index)=>({id:edge.id||`EDGE-${index+1}`,type:EDGE_TYPES.has(edge.type)?edge.type:'depends',...clone(edge)}))}
  graphProjection(){return freeze({owner:this.owner,identity:{id:this.definition.id,revision:this.definition.revision},lifecycle:this.lifecycle,title:this.definition.title||'',tasks:clone(this.definition.tasks||[]),edges:this._edges(),environment:clone(this.definition.environment||{}),requiredTools:clone(this.definition.requiredTools||[]),selection:this.selectionContext(),sharedOwnerRequirements:['StructuredSurfaceHost','SpatialInteractionKernel','RelationInteractionOwner']})}
  selectionContext(){if(!this.selection)return freeze({kind:'lab',id:this.definition.id,title:this.definition.title||'',editable:this.lifecycle!=='PUBLISHED'});if(this.selection.kind==='edge'){const edge=this._edges().find(x=>x.id===this.selection.id);return freeze(edge?{kind:'branch',id:edge.id,title:edge.label||edge.condition||edge.type,editable:this.lifecycle!=='PUBLISHED',object:clone(edge)}:{kind:'missing',id:this.selection.id,editable:false})}const task=(this.definition.tasks||[]).find(x=>x.id===this.selection.id);return freeze(task?{kind:'task',id:task.id,title:task.title||task.id,editable:this.lifecycle!=='PUBLISHED',object:clone(task)}:{kind:'missing',id:this.selection.id,editable:false})}
  select(selection=null){this.selection=selection?clone(selection):null;return this.selectionContext()}
  _applyOperation(operation){
    const op=operation?.op;if(!op)throw Error('LAB_AUTHOR_OPERATION_REQUIRED');let tasks=clone(this.definition.tasks||[]),dependencies=clone(this.definition.dependencies||[]);
    if(op==='addTask'){const task=clone(operation.task||{});if(!task.id)throw Error('LAB_TASK_ID_REQUIRED');if(tasks.some(x=>x.id===task.id))throw Error('LAB_TASK_ID_DUPLICATE');tasks.push({id:task.id,title:task.title||'New task',nodeType:task.nodeType||'action',validation:task.validation||'UNBOUND',expectedSignal:task.expectedSignal||'',toolRefs:clone(task.toolRefs||[])});this.definition={...this.definition,tasks};return}
    if(op==='updateTask'){const i=tasks.findIndex(x=>x.id===operation.taskId);if(i<0)throw Error('LAB_TASK_NOT_FOUND');tasks[i]={...tasks[i],...clone(operation.patch||{}),id:tasks[i].id};this.definition={...this.definition,tasks};return}
    if(op==='removeTask'){const i=tasks.findIndex(x=>x.id===operation.taskId);if(i<0)throw Error('LAB_TASK_NOT_FOUND');tasks.splice(i,1);dependencies=dependencies.filter(x=>x.from!==operation.taskId&&x.to!==operation.taskId);this.definition={...this.definition,tasks,dependencies};return}
    if(op==='connect'){const edge=clone(operation.edge||{});if(!edge.from||!edge.to||edge.from===edge.to)throw Error('LAB_EDGE_ENDPOINTS_INVALID');if(!tasks.some(x=>x.id===edge.from)||!tasks.some(x=>x.id===edge.to))throw Error('LAB_EDGE_ENDPOINT_UNKNOWN');if(dependencies.some(x=>x.from===edge.from&&x.to===edge.to))throw Error('LAB_EDGE_DUPLICATE');const type=EDGE_TYPES.has(edge.type)?edge.type:'depends';dependencies.push({id:edge.id||`EDGE-${dependencies.length+1}`,from:edge.from,to:edge.to,type,label:edge.label||'',condition:edge.condition||''});this.definition={...this.definition,dependencies};return}
    if(op==='updateEdge'){const edges=this._edges(),match=edges.find(x=>x.id===operation.edgeId);if(!match)throw Error('LAB_EDGE_NOT_FOUND');const index=edges.findIndex(x=>x.id===operation.edgeId),patch=clone(operation.patch||{});dependencies[index]={...dependencies[index],...patch,id:dependencies[index].id||match.id};this.definition={...this.definition,dependencies};return}
    if(op==='removeEdge'){const edges=this._edges(),index=edges.findIndex(x=>x.id===operation.edgeId);if(index<0)throw Error('LAB_EDGE_NOT_FOUND');dependencies.splice(index,1);this.definition={...this.definition,dependencies};return}
    throw Error('LAB_AUTHOR_OPERATION_UNKNOWN:'+op);
  }
  author(patch={}){this._assertMutable();if(patch?.op)this._applyOperation(patch);else{const allowed=['title','tasks','dependencies','requiredTools','environment','knowledgeLinks','expectedSignals','resultSchema','completion','safety'];for(const key of Object.keys(patch))if(!allowed.includes(key))throw Error('LAB_FIELD_OUT_OF_SCOPE:'+key);this.definition={...this.definition,...clone(patch)}}this.version++;this.lifecycle='DIRTY';return {receipt:this._receipt('labs.author',{operation:patch?.op||'patch'}),snapshot:this.snapshot()}}
  publish({digest=null}={}){if(this.lifecycle==='PUBLISHED')return this.snapshot();const validation=this.validate();if(!validation.ok)throw Error('LAB_VALIDATION_REQUIRED_BEFORE_PUBLISH');const frozen=freeze({...clone(this.definition),digest:digest||null});this.publishedRevisions.push(frozen);this.definition=clone(frozen);this.version++;this.lifecycle='PUBLISHED';return this.snapshot()}
  revise({expectedVersion=this.version}={}){if(expectedVersion!==this.version)throw Error('STALE_LAB_VERSION');const source=freeze(clone(this.definition)),sourceLifecycle=this.lifecycle,sourceDigest=this.definition.digest||null;if(sourceLifecycle==='PUBLISHED'&&!this.publishedRevisions.some(item=>item.id===source.id&&item.revision===source.revision))this.publishedRevisions.push(source);this.version++;this.definition={...clone(source),revision:revisionAfter(source.revision),digest:null};this.sourceLineage=freeze({id:source.id,revision:source.revision,digest:sourceDigest,lifecycle:sourceLifecycle});this.lifecycle='DRAFT';const receipt=this._receipt('labs.revise',{sourceLineage:this.sourceLineage,successorRevision:this.definition.revision});return {receipt,snapshot:this.snapshot(),source}}
  validate(){
    const errors=[],tasks=this.definition.tasks||[],ids=tasks.map(x=>x.id),toolIds=new Set((this.definition.requiredTools||[]).map(x=>x.id));if(!uniq(ids))errors.push('tasks:duplicate-id');
    for(const t of tasks){if(!t?.id||!String(t.title||'').trim())errors.push(`${t?.id||'task'}:title-required`);if(!t?.validation||t.validation==='UNBOUND')errors.push(`${t?.id||'task'}:validation-required`);if(!t?.expectedSignal)errors.push(`${t?.id||'task'}:expected-signal-required`);for(const ref of t.toolRefs||[])if(!toolIds.has(typeof ref==='string'?ref:ref?.id))errors.push(`${t.id}:tool-ref-unresolved:${typeof ref==='string'?ref:ref?.id||'missing'}`)}
    const edges=this._edges(),edgeIds=edges.map(x=>x.id);if(!uniq(edgeIds))errors.push('dependencies:duplicate-id');for(const e of edges){if(!ids.includes(e.from)||!ids.includes(e.to)||e.from===e.to)errors.push(`${e.from}->${e.to}:invalid-dependency`);if(!EDGE_TYPES.has(e.type))errors.push(`${e.id}:edge-type-invalid`);if(['conditional','branch'].includes(e.type)&&!String(e.condition||e.label||'').trim())errors.push(`${e.id}:branch-condition-required`)}
    return freeze({ok:errors.length===0,errors,graph:{taskCount:tasks.length,edgeCount:edges.length,nonLinear:tasks.some(id=>edges.filter(e=>e.from===id.id).length>1)||edges.some(e=>['conditional','branch','optional'].includes(e.type))},mutated:false});
  }
  preflight({tools={},environmentBinding=null}={}){
    const validation=this.validate(),checks=(this.definition.requiredTools||[]).map(req=>{const provider=tools[req.id];if(!provider)return {kind:'tool',id:req.id,status:'UNAVAILABLE',reason:'Required tool provider unavailable'};if(req.revision&&provider.revision!==req.revision)return {kind:'tool',id:req.id,status:'STALE',reason:'Required tool revision changed'};return {kind:'tool',id:req.id,status:req.simulated===true?'SIMULATED':'READY',reason:req.simulated===true?'Explicit simulation-only tool':''}}),requiredCaps=this.definition.environment?.capabilities||[],boundCaps=environmentBinding?.capabilities||[];
    for(const cap of requiredCaps)checks.push({kind:'environment',id:cap,status:boundCaps.includes(cap)?'READY':'UNAVAILABLE',reason:boundCaps.includes(cap)?'':`Required environment capability ${cap} unavailable`});
    const requiredRevision=this.definition.environment?.revision||null,boundRevision=environmentBinding?.revision||null;if(requiredRevision)checks.push({kind:'environment',id:'revision',status:requiredRevision===boundRevision?'READY':'STALE',reason:requiredRevision===boundRevision?'':`Environment revision ${requiredRevision} required`});
    checks.unshift({kind:'definition',id:'publication',status:this.lifecycle==='PUBLISHED'?'READY':'BLOCKED',reason:this.lifecycle==='PUBLISHED'?'':'Run handoff requires an exact published Lab revision'});const blocked=!validation.ok||checks.some(x=>['UNAVAILABLE','STALE','BLOCKED'].includes(x.status));return freeze({owner:this.owner,status:blocked?'BLOCKED':'READY',validation,checks,simulationExplicit:checks.some(x=>x.status==='SIMULATED'),runStartAllowed:!blocked&&this.lifecycle==='PUBLISHED',sourceLifecycle:this.lifecycle,mutated:false});
  }
  handoff(context={}){if(this.lifecycle!=='PUBLISHED')return freeze({ok:false,code:'LAB_REVISION_NOT_PUBLISHED',reason:'Run/Lab-module handoff requires an exact published Lab revision.',preflight:this.preflight(context),mutated:false,runCreated:false,runtimeStateCreated:false,preview:true});const preflight=this.preflight(context);if(preflight.status!=='READY')return freeze({ok:false,code:'LAB_PREFLIGHT_BLOCKED',preflight,mutated:false,runCreated:false,runtimeStateCreated:false});const executionContext=context.executionContext||'STANDALONE',frozenInput=freeze({labRef:{id:this.definition.id,revision:this.definition.revision},environmentRequirements:clone(this.definition.environment||{}),environmentBinding:clone(context.environmentBinding||{}),executionContext,scenarioRef:executionContext==='SCENARIO_MODULE'?clone(context.scenarioRef||null):null});return freeze({ok:true,code:'LAB_MODULE_REF_READY',labRef:frozenInput.labRef,inputManifest:frozenInput,preflight,runIdentityAllocation:'DELEGATED_TO_RUNS',runCreated:false,runtimeStateCreated:false,canonicalPublication:false,preview:this.lifecycle!=='PUBLISHED'})}
}
